const normalized=(value:string)=>value.replaceAll("_","").toLowerCase();
export function characterColorFamily(characterId:string):string|null { const variant=CHARACTER_COLOR_VARIANTS.find(v=>v.id===characterId); return variant?.colorFamily ?? CHARACTER_THEMES[characterId] ?? null; }
export function matchedLoadoutVariant(partId:string, characterId:string):LoadoutVariant|undefined { const list=partId.startsWith("body.")?BODY_COLOR_VARIANTS:partId.startsWith("glider.")?GLIDER_COLOR_VARIANTS:[]; const exact=CHARACTER_LOADOUT_VARIANTS[characterId]?.[partId]; if(exact!==undefined)return list.find(v=>v.id===exact); const family=characterColorFamily(characterId); if(!family)return undefined; return list.find(v=>v.baseId===partId&&normalized(v.colorFamily)===normalized(family)); }
export function loadoutVariantById(id:string|undefined):LoadoutVariant|undefined { return id===undefined?undefined:[...CHARACTER_COLOR_VARIANTS,...BODY_COLOR_VARIANTS,...GLIDER_COLOR_VARIANTS].find(v=>v.id===id); }
